## Design Note

Internal representation: a sorted `list[tuple[int, int]]` of disjoint, non-touching half-open intervals, kept normalized at all times. `bisect` on the start coordinate gives O(log n) for `contains`/`overlaps`/`covers`; `add`/`remove` locate the affected slice via two bisects then do one slice assignment (O(log n + k)). Set operations use a two-pointer merge/scan in O(n+m). Thread-safety is not provided (single-threaded mutation is assumed); a `copy()` method exists for snapshotting.

### solution.py
```python
"""IntervalSet – a mutable set of half-open integer intervals [start, end)."""

from __future__ import annotations

import bisect
from typing import Iterable

__all__ = ["IntervalSet"]


class IntervalSet:
    """A mutable, normalized set of half-open integer intervals [start, end)."""

    __slots__ = ("_intervals",)

    # ------------------------------------------------------------------ init
    def __init__(self, intervals: Iterable[tuple[int, int]] | None = None) -> None:
        self._intervals: list[tuple[int, int]] = []
        if intervals is not None:
            for start, end in intervals:
                self.add(start, end)

    # -------------------------------------------------------------- validation
    @staticmethod
    def _validate_coord(x: object, name: str = "coordinate") -> None:
        if isinstance(x, bool):
            raise TypeError(f"{name} must be int, not bool")
        if not isinstance(x, int):
            raise TypeError(f"{name} must be int, got {type(x).__name__}")

    @classmethod
    def _validate_range(cls, start: object, end: object) -> None:
        cls._validate_coord(start, "start")
        cls._validate_coord(end, "end")
        if start > end:  # type: ignore[operator]
            raise ValueError(f"start ({start}) > end ({end})")

    # -------------------------------------------------------------------- add
    def add(self, start: int, end: int) -> None:
        self._validate_range(start, end)
        if start == end:
            return
        iv = self._intervals
        # Lower bound: first interval whose end >= start (overlap or touch).
        idx = bisect.bisect_right(iv, (start, float("inf"))) - 1
        lo = idx if (idx >= 0 and iv[idx][1] >= start) else idx + 1
        # Upper bound: first interval whose start > end.
        hi = bisect.bisect_right(iv, (end, float("inf")))

        if lo >= hi:
            bisect.insort(iv, (start, end))
            return

        new_start = min(start, iv[lo][0])
        new_end = max(end, iv[hi - 1][1])
        iv[lo:hi] = [(new_start, new_end)]

    # ----------------------------------------------------------------- remove
    def remove(self, start: int, end: int) -> None:
        self._validate_range(start, end)
        if start == end:
            return
        iv = self._intervals
        # Lower bound: first interval whose end > start (strict overlap).
        idx = bisect.bisect_right(iv, (start, float("inf"))) - 1
        lo = idx if (idx >= 0 and iv[idx][1] > start) else idx + 1
        # Upper bound: first interval whose start >= end.
        hi = bisect.bisect_left(iv, (end, float("-inf")))

        if lo >= hi:
            return

        new_slice: list[tuple[int, int]] = []
        for i in range(lo, hi):
            s, e = iv[i]
            if s < start:
                new_slice.append((s, start))
            if e > end:
                new_slice.append((end, e))
        iv[lo:hi] = new_slice

    # --------------------------------------------------------------- contains
    def contains(self, x: int) -> bool:
        self._validate_coord(x, "x")
        iv = self._intervals
        idx = bisect.bisect_right(iv, (x, float("inf"))) - 1
        if idx < 0:
            return False
        return iv[idx][0] <= x < iv[idx][1]

    # --------------------------------------------------------------- overlaps
    def overlaps(self, start: int, end: int) -> bool:
        self._validate_range(start, end)
        if start == end:
            return False
        iv = self._intervals
        idx = bisect.bisect_right(iv, (start, float("inf"))) - 1
        if idx >= 0 and iv[idx][1] > start:
            return True
        idx += 1
        if idx < len(iv) and iv[idx][0] < end:
            return True
        return False

    # ----------------------------------------------------------------- covers
    def covers(self, start: int, end: int) -> bool:
        self._validate_range(start, end)
        if start == end:
            return True
        iv = self._intervals
        idx = bisect.bisect_right(iv, (start, float("inf"))) - 1
        if idx < 0:
            return False
        s, e = iv[idx]
        return s <= start and e >= end

    # ------------------------------------------------------------------ gaps
    def gaps(self, start: int, end: int) -> list[tuple[int, int]]:
        self._validate_range(start, end)
        if start == end:
            return []
        iv = self._intervals
        idx = bisect.bisect_right(iv, (start, float("inf"))) - 1
        if idx < 0 or iv[idx][1] <= start:
            idx += 1
        result: list[tuple[int, int]] = []
        cur = start
        while idx < len(iv) and iv[idx][0] < end:
            s, e = iv[idx]
            if s > cur:
                result.append((cur, min(s, end)))
            cur = max(cur, e)
            if cur >= end:
                break
            idx += 1
        if cur < end:
            result.append((cur, end))
        return result

    # ----------------------------------------------------------- total_length
    def total_length(self) -> int:
        return sum(e - s for s, e in self._intervals)

    # ------------------------------------------------------------------ copy
    def copy(self) -> IntervalSet:
        new = IntervalSet.__new__(IntervalSet)
        new._intervals = list(self._intervals)
        return new

    # -------------------------------------------------------- set operations
    def union(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(f"union requires IntervalSet, got {type(other).__name__}")
        result = IntervalSet.__new__(IntervalSet)
        result._intervals = self._merge_sorted(self._intervals, other._intervals)
        return result

    def intersection(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(
                f"intersection requires IntervalSet, got {type(other).__name__}"
            )
        result = IntervalSet.__new__(IntervalSet)
        result._intervals = self._intersect_sorted(self._intervals, other._intervals)
        return result

    def difference(self, other: IntervalSet) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            raise TypeError(
                f"difference requires IntervalSet, got {type(other).__name__}"
            )
        result = IntervalSet.__new__(IntervalSet)
        result._intervals = self._subtract_sorted(self._intervals, other._intervals)
        return result

    # ---------------------------------------------------- internal merge utils
    @staticmethod
    def _merge_sorted(
        a: list[tuple[int, int]], b: list[tuple[int, int]]
    ) -> list[tuple[int, int]]:
        result: list[tuple[int, int]] = []
        i = j = 0
        na, nb = len(a), len(b)
        while i < na or j < nb:
            if j >= nb or (i < na and a[i][0] <= b[j][0]):
                s, e = a[i]
                i += 1
            else:
                s, e = b[j]
                j += 1
            if result and result[-1][1] >= s:
                result[-1] = (result[-1][0], max(result[-1][1], e))
            else:
                result.append((s, e))
        return result

    @staticmethod
    def _intersect_sorted(
        a: list[tuple[int, int]], b: list[tuple[int, int]]
    ) -> list[tuple[int, int]]:
        result: list[tuple[int, int]] = []
        i = j = 0
        na, nb = len(a), len(b)
        while i < na and j < nb:
            s = max(a[i][0], b[j][0])
            e = min(a[i][1], b[j][1])
            if s < e:
                result.append((s, e))
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return result

    @staticmethod
    def _subtract_sorted(
        a: list[tuple[int, int]], b: list[tuple[int, int]]
    ) -> list[tuple[int, int]]:
        result: list[tuple[int, int]] = []
        j = 0
        nb = len(b)
        for s, e in a:
            cur = s
            while j < nb and b[j][0] < e:
                bs, be = b[j]
                if bs > cur:
                    result.append((cur, min(bs, e)))
                cur = max(cur, be)
                if cur >= e:
                    break
                j += 1
            if cur < e:
                result.append((cur, e))
        return result

    # ------------------------------------------------------- dunder methods
    def __iter__(self):
        return iter(self._intervals)

    def __len__(self) -> int:
        return len(self._intervals)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self._intervals == other._intervals

    __hash__ = None  # type: ignore[assignment]

    def __or__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.union(other)

    def __and__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.intersection(other)

    def __sub__(self, other: object) -> IntervalSet:
        if not isinstance(other, IntervalSet):
            return NotImplemented
        return self.difference(other)

    def __repr__(self) -> str:
        return f"IntervalSet({self._intervals})"
```

### test_solution.py
```python
"""Comprehensive tests for the IntervalSet module."""

import pytest
import solution
from solution import IntervalSet


# ======================================================================
# Validation
# ======================================================================

class TestValidation:
    def test_bool_rejected_as_start(self):
        with pytest.raises(TypeError):
            IntervalSet().add(True, 5)

    def test_bool_rejected_as_end(self):
        with pytest.raises(TypeError):
            IntervalSet().add(0, False)

    def test_bool_rejected_in_contains(self):
        with pytest.raises(TypeError):
            IntervalSet().contains(True)

    def test_float_rejected(self):
        with pytest.raises(TypeError):
            IntervalSet().add(1.0, 3.0)

    def test_string_rejected(self):
        with pytest.raises(TypeError):
            IntervalSet().add("1", "3")

    def test_none_rejected(self):
        with pytest.raises(TypeError):
            IntervalSet().add(None, 5)

    def test_start_gt_end_raises_value_error(self):
        with pytest.raises(ValueError):
            IntervalSet().add(5, 3)

    def test_start_gt_end_remove(self):
        with pytest.raises(ValueError):
            IntervalSet().remove(5, 3)

    def test_start_gt_end_overlaps(self):
        with pytest.raises(ValueError):
            IntervalSet().overlaps(5, 3)

    def test_start_gt_end_covers(self):
        with pytest.raises(ValueError):
            IntervalSet().covers(5, 3)

    def test_start_gt_end_gaps(self):
        with pytest.raises(ValueError):
            IntervalSet().gaps(5, 3)

    def test_constructor_validates(self):
        with pytest.raises(TypeError):
            IntervalSet([(True, 5)])
        with pytest.raises(ValueError):
            IntervalSet([(5, 3)])

    def test_set_unchanged_on_validation_error(self):
        s = IntervalSet([(0, 10)])
        with pytest.raises(TypeError):
            s.add(1.5, 5)
        assert list(s) == [(0, 10)]


# ======================================================================
# Basic add / contains / remove
# ======================================================================

class TestBasicOperations:
    def test_add_and_contains(self):
        s = IntervalSet()
        s.add(1, 5)
        assert s.contains(1)
        assert s.contains(4)
        assert not s.contains(0)
        assert not s.contains(5)

    def test_add_empty_range(self):
        s = IntervalSet()
        s.add(3, 3)
        assert len(s) == 0
        assert not s.contains(3)

    def test_remove_empty_range(self):
        s = IntervalSet([(0, 10)])
        s.remove(5, 5)
        assert list(s) == [(0, 10)]

    def test_remove_splits_interval(self):
        s = IntervalSet([(0, 10)])
        s.remove(3, 5)
        assert list(s) == [(0, 3), (5, 10)]

    def test_remove_left_shrink(self):
        s = IntervalSet([(0, 10)])
        s.remove(0, 3)
        assert list(s) == [(3, 10)]

    def test_remove_right_shrink(self):
        s = IntervalSet([(0, 10)])
        s.remove(7, 10)
        assert list(s) == [(0, 7)]

    def test_remove_entire_interval(self):
        s = IntervalSet([(0, 10)])
        s.remove(0, 10)
        assert len(s) == 0

    def test_remove_non_overlapping_is_noop(self):
        s = IntervalSet([(0, 5)])
        s.remove(10, 15)
        assert list(s) == [(0, 5)]

    def test_remove_spanning_multiple_intervals(self):
        s = IntervalSet([(0, 3), (5, 8), (10, 13)])
        s.remove(2, 11)
        assert list(s) == [(0, 2), (11, 13)]

    def test_remove_all(self):
        s = IntervalSet([(0, 3), (5, 8)])
        s.remove(0, 10)
        assert len(s) == 0


# ======================================================================
# Merging (adjacent intervals)
# ======================================================================

class TestMerging:
    def test_adjacent_merge(self):
        s = IntervalSet()
        s.add(1, 3)
        s.add(3, 5)
        assert list(s) == [(1, 5)]

    def test_touching_on_left(self):
        s = IntervalSet([(5, 10)])
        s.add(0, 5)
        assert list(s) == [(0, 10)]

    def test_overlap_merge(self):
        s = IntervalSet([(0, 5)])
        s.add(3, 8)
        assert list(s) == [(0, 8)]

    def test_contained_add(self):
        s = IntervalSet([(0, 10)])
        s.add(3, 5)
        assert list(s) == [(0, 10)]

    def test_add_spanning_multiple(self):
        s = IntervalSet([(0, 2), (4, 6), (8, 10)])
        s.add(1, 9)
        assert list(s) == [(0, 10)]

    def test_many_adjacent_merges(self):
        s = IntervalSet()
        for i in range(100):
            s.add(i, i + 1)
        assert list(s) == [(0, 100)]


# ======================================================================
# Negative and large coordinates
# ======================================================================

class TestEdgeCoordinates:
    def test_negative_coords(self):
        s = IntervalSet([(-10, -5)])
        assert s.contains(-10)
        assert s.contains(-6)
        assert not s.contains(-5)
        assert not s.contains(-11)

    def test_large_coords(self):
        big = 10**18
        s = IntervalSet([(big, big + 1)])
        assert s.contains(big)
        assert not s.contains(big + 1)

    def test_spanning_zero(self):
        s = IntervalSet([(-5, 5)])
        assert s.contains(0)
        assert s.total_length() == 10


# ======================================================================
# overlaps / covers
# ======================================================================

class TestOverlapsCovers:
    def test_overlaps_basic(self):
        s = IntervalSet([(0, 5)])
        assert s.overlaps(3, 7)
        assert s.overlaps(0, 1)
        assert not s.overlaps(5, 8)  # touching, not overlapping
        assert not s.overlaps(5, 6)
        assert not s.overlaps(-3, 0)  # touching on left

    def test_overlaps_empty_range(self):
        s = IntervalSet([(0, 5)])
        assert not s.overlaps(3, 3)

    def test_overlaps_no_intervals(self):
        s = IntervalSet()
        assert not s.overlaps(0, 10)

    def test_covers_basic(self):
        s = IntervalSet([(0, 10)])
        assert s.covers(0, 10)
        assert s.covers(2, 5)
        assert not s.covers(0, 11)
        assert not s.covers(-1, 5)

    def test_covers_empty_range(self):
        s = IntervalSet()
        assert s.covers(5, 5)

    def test_covers_spanning_gap(self):
        s = IntervalSet([(0, 3), (5, 8)])
        assert not s.covers(0, 8)
        assert s.covers(0, 3)
        assert s.covers(5, 8)

    def test_covers_single_interval(self):
        s = IntervalSet([(2, 6)])
        assert s.covers(2, 6)
        assert s.covers(3, 5)
        assert not s.covers(1, 6)
        assert not s.covers(2, 7)


# ======================================================================
# gaps
# ======================================================================

class TestGaps:
    def test_gaps_basic(self):
        s = IntervalSet([(2, 4), (6, 8)])
        assert s.gaps(0, 10) == [(0, 2), (4, 6), (8, 10)]

    def test_gaps_clipped(self):
        s = IntervalSet([(2, 4), (6, 8)])
        assert s.gaps(3, 7) == [(4, 6)]

    def test_gaps_empty_window(self):
        s = IntervalSet([(2, 4)])
        assert s.gaps(5, 5) == []

    def test_gaps_fully_covered(self):
        s = IntervalSet([(0, 10)])
        assert s.gaps(2, 8) == []

    def test_gaps_no_intervals(self):
        s = IntervalSet()
        assert s.gaps(0, 5) == [(0, 5)]

    def test_gaps_interval_before_window(self):
        s = IntervalSet([(0, 3)])
        assert s.gaps(3, 7) == [(3, 7)]

    def test_gaps_interval_after_window(self):
        s = IntervalSet([(10, 15)])
        assert s.gaps(0, 5) == [(0, 5)]

    def test_gaps_clipped_by_window(self):
        s = IntervalSet([(0, 2), (4, 6)])
        assert s.gaps(1, 5) == [(2, 4)]


# ======================================================================
# total_length / len / iter
# ======================================================================

class TestLengthAndIteration:
    def test_total_length(self):
        s = IntervalSet([(0, 5), (10, 13)])
        assert s.total_length() == 8

    def test_total_length_empty(self):
        assert IntervalSet().total_length() == 0

    def test_len_is_interval_count(self):
        s = IntervalSet([(0, 100)])
        assert len(s) == 1
        s.add(200, 300)
        assert len(s) == 2

    def test_len_empty(self):
        assert len(IntervalSet()) == 0

    def test_bool_falsy_empty(self):
        assert not IntervalSet()

    def test_bool_truthy_nonempty(self):
        assert IntervalSet([(0, 1)])

    def test_iter(self):
        s = IntervalSet([(5, 8), (0, 2)])
        assert list(s) == [(0, 2), (5, 8)]

    def test_iter_empty(self):
        assert list(IntervalSet()) == []


# ======================================================================
# Constructor
# ======================================================================

class TestConstructor:
    def test_default_empty(self):
        s = IntervalSet()
        assert len(s) == 0

    def test_from_list(self):
        s = IntervalSet([(0, 5), (3, 8)])
        assert list(s) == [(0, 8)]

    def test_from_generator(self):
        s = IntervalSet((i, i + 1) for i in range(5))
        assert list(s) == [(0, 5)]

    def test_order_independence(self):
        a = IntervalSet([(5, 8), (0, 2)])
        b = IntervalSet([(0, 2), (5, 8)])
        assert a == b
        assert list(a) == list(b)


# ======================================================================
# copy
# ======================================================================

class TestCopy:
    def test_copy_independent(self):
        s = IntervalSet([(0, 5)])
        c = s.copy()
        c.add(10, 15)
        assert list(s) == [(0, 5)]
        assert list(c) == [(0, 5), (10, 15)]

    def test_copy_equal(self):
        s = IntervalSet([(0, 5), (10, 15)])
        assert s.copy() == s


# ======================================================================
# Set operations
# ======================================================================

class TestSetOperations:
    def test_union(self):
        a = IntervalSet([(0, 5)])
        b = IntervalSet([(3, 8)])
        u = a.union(b)
        assert list(u) == [(0, 8)]
        # operands unchanged
        assert list(a) == [(0, 5)]
        assert list(b) == [(3, 8)]

    def test_union_disjoint(self):
        a = IntervalSet([(0, 2)])
        b = IntervalSet([(5, 7)])
        assert list(a | b) == [(0, 2), (5, 7)]

    def test_union_adjacent(self):
        a = IntervalSet([(0, 3)])
        b = IntervalSet([(3, 6)])
        assert list(a | b) == [(0, 6)]

    def test_union_empty(self):
        a = IntervalSet([(0, 5)])
        assert (a | IntervalSet()) == a
        assert (IntervalSet() | a) == a

    def test_intersection(self):
        a = IntervalSet([(0, 10)])
        b = IntervalSet([(5, 15)])
        assert list(a & b) == [(5, 10)]

    def test_intersection_disjoint(self):
        a = IntervalSet([(0, 3)])
        b = IntervalSet([(5, 8)])
        assert list(a & b) == []

    def test_intersection_nested(self):
        a = IntervalSet([(0, 20)])
        b = IntervalSet([(5, 10), (15, 18)])
        assert list(a & b) == [(5, 10), (15, 18)]

    def test_difference(self):
        a = IntervalSet([(0, 10)])
        b = IntervalSet([(3, 5)])
        assert list(a - b) == [(0, 3), (5, 10)]

    def test_difference_no_overlap(self):
        a = IntervalSet([(0, 5)])
        b = IntervalSet([(10, 15)])
        assert list(a - b) == [(0, 5)]

    def test_difference_complete(self):
        a = IntervalSet([(0, 5)])
        b = IntervalSet([(0, 5)])
        assert list(a - b) == []

    def test_difference_multi(self):
        a = IntervalSet([(0, 20)])
        b = IntervalSet([(2, 5), (10, 15)])
        assert list(a - b) == [(0, 2), (5, 10), (15, 20)]

    def test_operators_not_implemented(self):
        s = IntervalSet([(0, 5)])
        with pytest.raises(TypeError):
            s | 5
        with pytest.raises(TypeError):
            s & "hello"
        with pytest.raises(TypeError):
            s - [1, 2]

    def test_named_methods_raise_type_error(self):
        s = IntervalSet([(0, 5)])
        with pytest.raises(TypeError):
            s.union(5)
        with pytest.raises(TypeError):
            s.intersection(5)
        with pytest.raises(TypeError):
            s.difference(5)

    def test_union_interleaved(self):
        a = IntervalSet([(0, 3), (5, 8)])
        b = IntervalSet([(1, 6)])
        assert list(a | b) == [(0, 8)]


# ======================================================================
# Equality / hashing
# ======================================================================

class TestEqualityHashing:
    def test_equal_same_coverage(self):
        a = IntervalSet([(0, 5)])
        b = IntervalSet([(0, 3), (3, 5)])
        assert a == b

    def test_not_equal(self):
        a = IntervalSet([(0, 5)])
        b = IntervalSet([(0, 6)])
        assert a != b

    def test_eq_with_non_intervalset(self):
        s = IntervalSet()
        assert s != []
        assert s != 5
        assert not (s == [])

    def test_unhashable(self):
        s = IntervalSet()
        with pytest.raises(TypeError):
            hash(s)

    def test_empty_equals_empty(self):
        assert IntervalSet() == IntervalSet()


# ======================================================================
# repr
# ======================================================================

class TestRepr:
    def test_repr_contains_intervals(self):
        s = IntervalSet([(0, 5)])
        r = repr(s)
        assert "IntervalSet" in r
        assert "(0, 5)" in r

    def test_repr_empty(self):
        assert repr(IntervalSet()) == "IntervalSet([])"


# ======================================================================
# Stress / performance sanity
# ======================================================================

class TestStress:
    def test_many_fragments_add(self):
        """Adding many small non-adjacent fragments should stay linear-ish."""
        s = IntervalSet()
        # Add 10k non-adjacent intervals
        for i in range(10_000):
            s.add(i * 3, i * 3 + 1)
        assert len(s) == 10_000
        assert s.total_length() == 10_000

    def test_many_fragments_then_merge(self):
        s = IntervalSet()
        for i in range(5_000):
            s.add(i * 2, i * 2 + 1)
        # Fill gaps → should merge into one
        for i in range(5_000):
            s.add(i * 2 + 1, i * 2 + 2)
        assert list(s) == [(0, 10_000)]

    def test_remove_many(self):
        s = IntervalSet([(0, 100_000)])
        for i in range(0, 100_000, 2):
            s.remove(i, i + 1)
        assert s.total_length() == 50_000
        assert len(s) == 50_000

    def test_contains_log_time(self):
        s = IntervalSet()
        for i in range(50_000):
            s.add(i * 10, i * 10 + 5)
        # Just verify correctness at scale (speed is implicit via O(log n))
        assert s.contains(0)
        assert not s.contains(5)
        assert s.contains(499_995)
        assert not s.contains(499_990 + 5)

    def test_union_large(self):
        a = IntervalSet((i * 4, i * 4 + 2) for i in range(5_000))
        b = IntervalSet((i * 4 + 2, i * 4 + 4) for i in range(5_000))
        u = a | b
        assert list(u) == [(0, 20_000)]

    def test_idempotent_add(self):
        s = IntervalSet([(0, 10)])
        for _ in range(100):
